.dm-crx{display:grid;grid-template-columns:210px 1fr;overflow:hidden;min-height:330px}
@media (max-width:720px){.dm-crx{grid-template-columns:1fr}.dm-crx-side{border-right:0!important;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}}
.dm-crx-side{border-right:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);padding:10px;display:flex;flex-direction:column;gap:6px;min-width:0}
.dm-crx-sh{display:flex;justify-content:space-between;align-items:baseline;padding:var(--dm-s-1) 6px;font-size:12.5px}
.dm-crx-sh b{font-weight:500}
.dm-crx-files{display:flex;flex-direction:column;gap:2px}
.dm-crx-f{display:flex;align-items:center;gap:var(--dm-s-2);padding:7px var(--dm-s-2);border-radius:10px;font-size:12.5px;text-align:left;transition:background .25s;min-width:0}
@media (hover:hover) and (pointer:fine){.dm-crx-f:hover{background:var(--dm-row)}}
.dm-crx-f.dm-on{background:var(--dm-sel)}
.dm-crx-f .dm-nm{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-family:var(--dm-mono);font-size:11.5px}
.dm-crx-f .dm-st{width:16px;height:16px;display:grid;place-items:center;color:var(--dm-faint)}
.dm-crx-f.dm-kept .dm-st{color:var(--dm-ok)}.dm-crx-f.dm-undone .dm-st{color:var(--dm-muted)}
.dm-crx-main{display:flex;flex-direction:column;min-width:0}
.dm-crx-mh{display:flex;align-items:center;gap:6px;padding:10px var(--dm-s-3);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-crx-fn{font-size:12px;font-family:var(--dm-mono);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0}
.dm-crx-sp{flex:1}
.dm-crx-diff{padding:var(--dm-s-2) 0;font-family:var(--dm-mono);font-size:12px;line-height:1.75;overflow-x:auto}
.dm-crx-hk{margin:0 10px 10px;border-radius:10px;overflow:auto hidden;transition:opacity .35s}
.dm-crx-hh{display:flex;align-items:center;gap:6px;padding:var(--dm-s-1) 6px var(--dm-s-1) 10px;font-family:var(--dm-sans);font-size:12px;color:var(--dm-fg2);background:var(--dm-chip)}
.dm-crx-hh .dm-sp{flex:1}
.dm-crx-hh .dm-pill{height:24px;padding:0 9px;font-size:12px}
.dm-crx-l{display:flex;position:relative;white-space:pre;padding-right:10px}
.dm-crx-l .dm-ln{width:36px;text-align:right;padding-right:10px;color:var(--dm-muted);flex:none;user-select:none}
.dm-crx-l.dm-add{background:var(--dm-ok-bg)}.dm-crx-l.dm-add .dm-c::before{content:"+ ";color:var(--dm-ok)}
.dm-crx-l.dm-del{background:var(--dm-bad-bg)}.dm-crx-l.dm-del .dm-c::before{content:"− ";color:var(--dm-bad)}
.dm-crx-l:is(.dm-add,.dm-del) .dm-ln{color:var(--dm-fg2)}
.dm-crx-l.dm-ctx .dm-c::before{content:"  "}
.dm-crx-l .dm-cm{position:absolute;left:4px;top:3px;width:18px;height:18px;border-radius:6px;background:var(--dm-accent);color:var(--dm-on-accent);display:grid;place-items:center;opacity:0;transform:scale(.7);transition:opacity .2s,transform .25s var(--dm-ease)}
/* the hunk scrolls sideways and cuts anything outside its last line: the ring is drawn inside, with a gap of the surface
   between it and the fill */
.dm-crx-l .dm-cm:focus-visible{outline-offset:-2px;box-shadow:inset 0 0 0 3.5px var(--dm-surface);opacity:1;transform:none}
@media (hover:hover) and (pointer:fine){.dm-crx-l:hover .dm-cm{opacity:1;transform:none}}
.dm-crx-hk.dm-kept .dm-crx-l.dm-del{display:none}.dm-crx-hk.dm-kept .dm-crx-l.dm-add{background:transparent}.dm-crx-hk.dm-kept .dm-crx-l.dm-add .dm-c::before{content:"  "}
.dm-crx-hk.dm-undone .dm-crx-l.dm-add{display:none}.dm-crx-hk.dm-undone .dm-crx-l.dm-del{background:transparent}.dm-crx-hk.dm-undone .dm-crx-l.dm-del .dm-c::before{content:"  "}
.dm-crx-hk.dm-kept .dm-crx-hh,.dm-crx-hk.dm-undone .dm-crx-hh{color:var(--dm-muted)}
.dm-crx-cmt{font-family:var(--dm-sans);margin:var(--dm-s-1) 10px 6px 36px;display:flex;gap:6px;align-items:center;padding:6px;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent)}
@supports (corner-shape:squircle){.dm-crx-cmt:not(.dm-sent){corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.dm-crx-cmt input{flex:1;min-width:0;border:0;outline:0;background:transparent;font:inherit;font-size:12.5px;color:var(--dm-fg);padding:0 6px}
.dm-crx-cmt:has(input:focus){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.dm-crx-cmt.dm-sent{background:var(--dm-sel);box-shadow:none;font-size:12.5px;padding:6px 10px}

